using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class SilverSheetVerify {
 public static object Main(){var paths=new[]{"Assets/Mock/Effects/JustAvoidCounterFirstCut.mat","Assets/Mock/Effects/JustAvoidCounterCut.mat"};var materials=paths.Select(path=>{var m=AssetDatabase.LoadAssetAtPath<Material>(path);ShaderUtil.CompilePass(m,0,true);return new{path,passCompiled=ShaderUtil.IsPassCompiled(m,0),shader=AssetDatabase.GetAssetPath(m.shader),width=m.GetFloat("_CoreWidth"),length=m.GetFloat("_CoreLength"),sheetWidth=m.GetFloat("_SheetWidth"),sheetIntensity=m.GetFloat("_SheetIntensity"),fade=m.GetFloat("_FadeDuration"),residual=m.GetFloat("_ResidualGlowDuration"),depth=m.GetFloat("_ZTest"),errors=ShaderUtil.GetShaderMessages(m.shader).Where(x=>x.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error).Select(x=>x.message).ToArray()};}).ToArray();var c=AssetDatabase.LoadAssetAtPath<JustAvoidCounterConfig>("Assets/Mock/ScriptableObjects/JustAvoidCounterConfig.asset");var result=new{materials,hitStop=new[]{c.First.HitStop,c.Second.HitStop},poolPrefabs=new[]{AssetDatabase.GetAssetPath(c.FirstCFX),AssetDatabase.GetAssetPath(c.FinisherCFX)}};File.WriteAllText("Artifacts/CutSilverSheet/EditorVerification.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
